// Flattens one Evinor delivery into the fields the rest of the workflow uses,
// and adds it to the daily digest buffer.
// Payload reference: https://github.com/evinor-ai/n8n-nodes-evinor
const SUBJECT_ROLE = {
  FUND_RAISING: 'COMPANY_RAISING_FUNDS',
  LEADERSHIP_CHANGE: 'COMPANY_NAME',
  LAYOFF: 'COMPANY_NAME',
};

const store = $getWorkflowStaticData('global');
store.digest = store.digest ?? [];

const out = [];
for (const item of $input.all()) {
  const e = item.json;
  const d = e.details ?? {};
  const roles = Array.isArray(d.roles) ? d.roles : [];
  const first = (code) => roles.find((r) => r.code === code);
  const every = (code) => roles.filter((r) => r.code === code).map((r) => r.textValue);

  const eventType = e.eventCodeName ?? d.templateCodeName ?? '';
  const subject = first(SUBJECT_ROLE[eventType] ?? 'COMPANY_NAME');
  const amount = first('AMOUNT_RAISED');

  // Respect the date's precision: a MONTH (or null) precision date has no real day.
  let eventDate = '';
  if (e.eventDate?.value) {
    eventDate = e.eventDate.precision === 'DAY'
      ? e.eventDate.value.slice(0, 10)
      : e.eventDate.value.slice(0, 7);
    if (e.eventDate.source === 'ESTIMATED') eventDate += ' (estimated)';
  }

  const band = d.confidence?.band ?? 'UNKNOWN';
  const company = subject?.textValue ?? '';
  const outlets = (d.reportingOutlets ?? []).map((o) => o.name).filter(Boolean).join(', ');

  let reviewReason = '';
  if (!company) reviewReason = 'No company on the event';
  else if (band !== 'HIGH') reviewReason = `Confidence is ${band}`;

  const ev = {
    eventId: e.externalEventId ?? d.incidentId ?? '',
    eventType,
    sentence: d.generatedSentence ?? d.summaryText ?? '',
    band,
    company,
    entityId: subject?.namedEntityId ?? '',
    amount: amount?.parsedAmount ?? '',
    amountUnit: amount?.parsedAmountUnit ?? '',
    roundType: first('FUNDING_ROUND_TYPE')?.textValue ?? '',
    investors: every('INVESTING_COMPANY_NAME').join(', '),
    roleTitle: first('ROLE_TITLE')?.textValue ?? '',
    incomingPerson: first('INCOMING_PERSON')?.textValue ?? '',
    outgoingPerson: first('OUTGOING_PERSON')?.textValue ?? '',
    affectedEmployees: first('AFFECTED_EMPLOYEES_COUNT')?.textValue ?? '',
    eventDate,
    outlets,
    reportCount: d.matchingReportCount ?? 0,
    sourceKind: d.triggeringReport?.sourceKind ?? '',
    isTest: e.isTest === true,
    autoRoute: reviewReason === '',
    reviewReason,
  };

  if (!ev.isTest) {
    store.digest.push({ eventType: ev.eventType, sentence: ev.sentence, band: ev.band, outlets: ev.outlets });
    store.digest = store.digest.slice(-500);
  }
  out.push({ json: ev });
}
return out;

// Review-only boundary: the HTTP API is mocked in Code; no network is used.
// Request expression is from the respective Evinor workflow export, verbatim.
const requestBody = JSON.parse( JSON.stringify({
  filterGroups: [
    { filters: [{ propertyName: 'evinor_entity_id', operator: 'EQ', value: $json.entityId || 'none' }] },
    { filters: [{ propertyName: 'name', operator: 'EQ', value: $json.company }] }
  ],
  properties: ['name', 'domain', 'hubspot_owner_id', 'evinor_entity_id'],
  limit: 10
}) );
const companies = JSON.parse("[{\"id\":\"foreign-company\",\"properties\":{\"name\":\"Other Company\",\"evinor_entity_id\":\"none\",\"hubspot_owner_id\":\"foreign-owner\",\"domain\":\"foreign-company.example\"}}]");
const matched = companies.filter(company => requestBody.filterGroups.some(group =>
  group.filters.every(filter => {
    if (filter.operator !== 'EQ') throw new Error('Review fixture supports the source EQ filters only');
    return company.properties?.[filter.propertyName] === filter.value;
  })
));
return { json: { total: matched.length, results: matched.slice(0, requestBody.limit) } };

// Picks the CRM company. An exact evinor_entity_id match wins; otherwise a
// single exact-name match is accepted. Anything ambiguous goes to a person.
const ev = $('Normalize event').item.json;
const results = $json.results ?? [];
const byId = ev.entityId
  ? results.filter((c) => c.properties?.evinor_entity_id === ev.entityId)
  : [];
const candidates = byId.length > 0 ? byId : results;
const company = candidates.length === 1 ? candidates[0] : null;

let route;
let reviewReason = '';
if (!company) {
  route = 'review';
  reviewReason = candidates.length === 0
    ? `No HubSpot company matched "${ev.company}"`
    : `${candidates.length} HubSpot companies are named "${ev.company}". Set evinor_entity_id = ${ev.entityId || '(none on event)'} on the right one`;
} else if (!company.properties?.hubspot_owner_id) {
  route = 'lead';
} else if (ev.eventType === 'LAYOFF') {
  route = 'review';
  reviewReason = 'Layoff at an owned account: a person decides the tone';
} else {
  route = 'task';
}

const details = [
  ev.amount !== '' ? `Amount: ${ev.amount} ${ev.amountUnit}`.trim() : '',
  ev.roundType ? `Round: ${ev.roundType}` : '',
  ev.investors ? `Investors: ${ev.investors}` : '',
  ev.incomingPerson ? `Incoming: ${ev.incomingPerson}` : '',
  ev.outgoingPerson ? `Outgoing: ${ev.outgoingPerson}` : '',
  ev.roleTitle ? `Role: ${ev.roleTitle}` : '',
  ev.eventDate ? `Event date: ${ev.eventDate}` : '',
  `Reported by: ${ev.outlets || 'unnamed outlets'} (${ev.reportCount} reports)`,
  `Evinor event: ${ev.eventId}`,
].filter(Boolean);

return {
  json: {
    ...ev,
    route,
    reviewReason,
    hubspotCompanyId: company?.id ?? '',
    ownerId: company?.properties?.hubspot_owner_id ?? '',
    matchedBy: byId.length > 0 ? 'evinor_entity_id' : 'name',
    noteHtml: `<p><strong>${ev.sentence}</strong></p><p>${details.join('<br>')}</p>`,
    taskSubject: `${ev.eventType === 'FUND_RAISING' ? 'Funding' : 'Leadership change'}: ${ev.company}`,
    taskBody: `${ev.sentence}\n${details.join('\n')}`,
  },
};

// Generated by n8n-check. Fixed fixture, one run per node; leave this branch last.
function equalJson(a, b) {
  if (Object.is(a, b)) return true;
  if (!a || !b || typeof a !== 'object' || typeof b !== 'object') return false;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  const keys = Object.keys(a);
  return keys.length === Object.keys(b).length &&
    keys.every(key => Object.hasOwn(b, key) && equalJson(a[key], b[key]));
}
function checkItems(items, assertion) {
  const label = `${assertion.node}: output ${assertion.output ?? 0}`;
  if (assertion.count !== undefined && items.length !== assertion.count)
    throw new Error(`n8n-check: ${label} expected ${assertion.count} items, got ${items.length}`);
  if (assertion.equals !== undefined) {
    const values = items.map((item, index) => {
      if (!assertion.pluck) return item.json;
      let value = item;
      for (const key of assertion.pluck.split('.')) {
        if (value === null || typeof value !== 'object' || !Object.hasOwn(value, key))
          throw new Error(`n8n-check: ${label} item ${index} is missing ${assertion.pluck}`);
        value = value[key];
      }
      return value;
    });
    if (!equalJson(values, assertion.equals))
      throw new Error(`n8n-check: ${label}${assertion.pluck ? ` ${assertion.pluck}` : ''} differs. Expected ${JSON.stringify(assertion.equals)}; got ${JSON.stringify(values)}`);
  }
  return { node: assertion.node, output: assertion.output ?? 0, count: items.length, passed: true };
}
const assertions = JSON.parse("[{\"node\":\"Stable route output\",\"count\":1,\"equals\":[{\"route\":\"review\",\"companyId\":\"\",\"ownerId\":\"\"}]}]");
const checks = assertions.map(assertion => {
  const node = $(assertion.node);
  const items = node.isExecuted ? node.all(assertion.output ?? 0, 0) : [];
  return checkItems(items, assertion);
});
return [{ json: { status: 'passed', checks } }];
